const nextClaimSequence = `-- name: NextClaimSequence :one
SELECT nextval('claim_no_seq')::bigint AS seq
`

// NextClaimSequence takes the next number of claim_no_seq. The sequence never resets and never gives a number twice,
// so a rolled-back claim leaves a gap in the numbers.
func (q *Queries) NextClaimSequence(ctx context.Context) (int64, error) {
	row := q.db.QueryRow(ctx, nextClaimSequence)
	var seq int64
	err := row.Scan(&seq)
	return seq, err
}

const resubmitClaim = `-- name: ResubmitClaim :execrows
UPDATE claims
SET status = 'SUBMITTED', submitted_at = $1, updated_at = $1, version = version + 1
WHERE id = $2 AND version = $3
`

type ResubmitClaimParams struct {
	Now     pgtype.Timestamptz
	ID      uuid.UUID
	Version int32
}

func (q *Queries) ResubmitClaim(ctx context.Context, arg ResubmitClaimParams) (int64, error) {
	result, err := q.db.Exec(ctx, resubmitClaim, arg.Now, arg.ID, arg.Version)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const returnClaim = `-- name: ReturnClaim :execrows
UPDATE claims
SET status = 'RETURNED', return_count = return_count + 1, version = version + 1, updated_at = $1
WHERE id = $2 AND version = $3
`

type ReturnClaimParams struct {
	Now     pgtype.Timestamptz
	ID      uuid.UUID
	Version int32
}

// ReturnClaim sends a claim back to its requester: it adds one to the return count and to the version, but only while the
// version is still the one the caller read (BR-13). A return is a step in the review, so decided_at stays NULL. It
// returns the rows changed: 0 means the claim changed since.
func (q *Queries) ReturnClaim(ctx context.Context, arg ReturnClaimParams) (int64, error) {
	result, err := q.db.Exec(ctx, returnClaim, arg.Now, arg.ID, arg.Version)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const sendClaimToFinance = `-- name: SendClaimToFinance :execrows
UPDATE claims
SET status = 'PENDING_FINANCE', version = version + 1, updated_at = $1
WHERE id = $2 AND version = $3
`

type SendClaimToFinanceParams struct {
	Now     pgtype.Timestamptz
	ID      uuid.UUID
	Version int32
}

// SendClaimToFinance moves an approved high-value claim to PENDING_FINANCE and adds one to the version, but only while
// the version is still the one the caller read (BR-09, BR-13). The claim waits for a final decision, so decided_at
// stays NULL. It returns the rows changed: 0 means the claim changed since.
func (q *Queries) SendClaimToFinance(ctx context.Context, arg SendClaimToFinanceParams) (int64, error) {
	result, err := q.db.Exec(ctx, sendClaimToFinance, arg.Now, arg.ID, arg.Version)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

