const upsertSeedAccount = `-- name: UpsertSeedAccount :exec
INSERT INTO account (id, user_id, provider_id, account_id, password)
VALUES ($1, $2, 'credential', $3, $4)
ON CONFLICT (provider_id, account_id) DO UPDATE SET
  user_id = EXCLUDED.user_id,
  password = EXCLUDED.password,
  updated_at = now()
`

type UpsertSeedAccountParams struct {
	ID        uuid.UUID
	UserID    uuid.UUID
	AccountID string
	Password  pgtype.Text
}

// UpsertSeedAccount stores the bcrypt hash of a demo user's credential account. The account id is the user id,
// as Better Auth keys credential accounts.
func (q *Queries) UpsertSeedAccount(ctx context.Context, arg UpsertSeedAccountParams) error {
	_, err := q.db.Exec(ctx, upsertSeedAccount,
		arg.ID,
		arg.UserID,
		arg.AccountID,
		arg.Password,
	)
	return err
}

const upsertSeedUser = `-- name: UpsertSeedUser :one
INSERT INTO "user" (id, name, email, username, display_username, role, position, reviewer_id)
VALUES ($1, $2, $3, $4, $4, $5, $6, $7)
ON CONFLICT (username) DO UPDATE SET
  name = EXCLUDED.name,
  email = EXCLUDED.email,
  display_username = EXCLUDED.display_username,
  role = EXCLUDED.role,
  position = EXCLUDED.position,
  reviewer_id = EXCLUDED.reviewer_id,
  updated_at = now()
RETURNING id
`

type UpsertSeedUserParams struct {
	ID         uuid.UUID
	Name       string
	Email      string
	Username   string
	Role       string
	Position   string
	ReviewerID uuid.NullUUID
}

// UpsertSeedUser inserts a demo user, or updates the user with the same username. It returns the user id,
// which the row keeps across runs, so a reviewer_id taken from it stays valid.
func (q *Queries) UpsertSeedUser(ctx context.Context, arg UpsertSeedUserParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, upsertSeedUser,
		arg.ID,
		arg.Name,
		arg.Email,
		arg.Username,
		arg.Role,
		arg.Position,
		arg.ReviewerID,
	)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

const withdrawClaim = `-- name: WithdrawClaim :execrows
UPDATE claims
SET status = 'WITHDRAWN', version = version + 1, updated_at = $1
WHERE id = $2 AND version = $3
`

type WithdrawClaimParams struct {
	Now     pgtype.Timestamptz
	ID      uuid.UUID
	Version int32
}

// WithdrawClaim moves a claim to WITHDRAWN and adds one to the version, but only while the version is still the one the
// caller read (BR-13). A withdrawal is not a decision, so decided_at stays NULL. It returns the rows changed: 0 means the
// claim changed since.
func (q *Queries) WithdrawClaim(ctx context.Context, arg WithdrawClaimParams) (int64, error) {
	result, err := q.db.Exec(ctx, withdrawClaim, arg.Now, arg.ID, arg.Version)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
